export type Reader<T = any> = (text: string) => T;
export interface Fields {
  [key: string]: Reader | { each: Reader };
}
// A row's type is computed from the fields table's own type. A table whose
// type names its keys gives each key what its reader answers; a table typed
// as the general `Fields` gives every key `never | undefined`.
export type Row<F extends Fields> = { skipped: string[] } & {
  [K in keyof F]?: F[K] extends Reader<infer V>
    ? V
    : F[K] extends { each: Reader<infer V> }
      ? V[]
      : never;
};
export function many<T>(read: Reader<T>): { each: Reader<T> };
export function readLine<F extends Fields>(fields: F, line: string): Row<F>;
